/* ==================== GitHub 配置 ==================== */
const GITHUB_CONFIG = {
    owner: '1436121130-cpu',    // 👈 改成你的
    repo: 'lottery-data',          // 👈 你的仓库名
    token: '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'             // 👈 你的 GitHub Token
};

const API_BASE = `https://api.github.com/repos/${GITHUB_CONFIG.owner}/${GITHUB_CONFIG.repo}/contents`;

/* ==================== GitHub API ==================== */
async function githubGet(path) {
    const res = await fetch(`${API_BASE}/${path}`, {
        headers: { 'Authorization': `token ${GITHUB_CONFIG.token}` }
    });
    if (!res.ok) throw new Error('读取失败');
    const data = await res.json();
    return {
        content: JSON.parse(decodeURIComponent(escape(atob(data.content)))),
        sha: data.sha
    };
}

async function githubPut(path, content, sha, message) {
    const res = await fetch(`${API_BASE}/${path}`, {
        method: 'PUT',
        headers: {
            'Authorization': `token ${GITHUB_CONFIG.token}`,
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({
            message: message || 'update',
            content: btoa(unescape(encodeURIComponent(JSON.stringify(content)))),
            sha: sha
        })
    });
    if (!res.ok) throw new Error('保存失败');
    return await res.json();
}

/* ==================== 密码哈希 ==================== */
function hashPwd(pwd) {
    let hash = 0;
    for (let i = 0; i < pwd.length; i++) {
        const char = pwd.charCodeAt(i);
        hash = ((hash << 5) - hash) + char;
        hash |= 0;
    }
    return 'h_' + Math.abs(hash).toString(36);
}

/* ==================== 用户系统 ==================== */
let currentUser = null;
let userData = null;
let saveTimer = null;

async function doRegister() {
    const u = document.getElementById('regUser').value.trim();
    const p = document.getElementById('regPwd').value;
    const p2 = document.getElementById('regPwd2').value;
    const errEl = document.getElementById('regErr');

    if (u.length < 3 || u.length > 12) { errEl.textContent = '用户名需3-12位'; return; }
    if (p.length < 4) { errEl.textContent = '密码至少4位'; return; }
    if (p !== p2) { errEl.textContent = '两次密码不一致'; return; }

    errEl.textContent = '注册中...';

    try {
        const { content: users, sha } = await githubGet('users.json');
        
        if (users[u]) {
            errEl.textContent = '用户名已存在';
            return;
        }

        users[u] = {
            pwd: hashPwd(p),
            createdAt: new Date().toISOString()
        };

        await githubPut('users.json', users, sha, `注册: ${u}`);

        const { content: allData, sha: dataSha } = await githubGet('data.json');
        allData[u] = {
            points: 1000,
            bets: [],
            history: [],
            stats: { totalDraws: 0, totalSpent: 0, totalEarned: 0 },
            checkin: { lastDate: null, consecutiveDays: 0 },
            achievements: {},
            aiConfig: { enabled: false, types: ['ssq', 'dlt', 'plw'], mult: 1, count: 1 }
        };
        await githubPut('data.json', allData, dataSha, `初始化: ${u}`);

        currentUser = u;
        userData = allData[u];
        enterApp();

    } catch (e) {
        errEl.textContent = '注册失败：' + e.message;
    }
}

async function doLogin() {
    const u = document.getElementById('loginUser').value.trim();
    const p = document.getElementById('loginPwd').value;
    const errEl = document.getElementById('loginErr');

    if (!u || !p) { errEl.textContent = '请输入账号密码'; return; }
    errEl.textContent = '登录中...';

    try {
        const { content: users } = await githubGet('users.json');
        
        if (!users[u]) {
            errEl.textContent = '用户不存在';
            return;
        }

        if (users[u].pwd !== hashPwd(p)) {
            errEl.textContent = '密码错误';
            return;
        }

        const { content: allData } = await githubGet('data.json');
        currentUser = u;
        userData = allData[u] || {
            points: 1000, bets: [], history: [],
            stats: { totalDraws: 0, totalSpent: 0, totalEarned: 0 },
            checkin: { lastDate: null, consecutiveDays: 0 },
            achievements: {},
            aiConfig: { enabled: false, types: ['ssq', 'dlt', 'plw'], mult: 1, count: 1 }
        };

        enterApp();

    } catch (e) {
        errEl.textContent = '登录失败：' + e.message;
    }
}

function doLogout() {
    if (confirm('确定退出？')) {
        currentUser = null;
        userData = null;
        location.reload();
    }
}

function switchAuth(type) {
    document.getElementById('loginForm').style.display = type === 'login' ? 'block' : 'none';
    document.getElementById('registerForm').style.display = type === 'register' ? 'block' : 'none';
    document.getElementById('tabLogin').classList.toggle('active', type === 'login');
    document.getElementById('tabReg').classList.toggle('active', type === 'register');
    document.getElementById('loginErr').textContent = '';
    document.getElementById('regErr').textContent = '';
}

/* ==================== 数据同步 ==================== */
async function saveToGitHub() {
    if (!currentUser) return;
    if (saveTimer) clearTimeout(saveTimer);
    
    saveTimer = setTimeout(async () => {
        try {
            const { content: allData, sha } = await githubGet('data.json');
            allData[currentUser] = userData;
            await githubPut('data.json', allData, sha, `更新: ${currentUser}`);
            console.log('☁️ 已同步');
        } catch (e) {
            console.error('同步失败', e);
        }
    }, 2000);
}

function getPoints() { return userData?.points || 0; }

function setPoints(v) {
    if (!userData) return;
    userData.points = Math.max(0, v);
    updatePointsUI();
    saveToGitHub();
}

function addPoints(n) { setPoints(getPoints() + n); }

function deductPoints(n) {
    if (getPoints() < n) return false;
    setPoints(getPoints() - n);
    return true;
}

function updatePointsUI() {
    document.getElementById('userPoints').textContent = getPoints().toLocaleString();
}

/* ==================== 进入应用 ==================== */
function enterApp() {
    document.getElementById('authScreen').style.display = 'none';
    document.getElementById('appContainer').style.display = 'block';
    document.getElementById('userBadge').textContent = '👤 ' + currentUser;
    
    buildAppUI();
    updatePointsUI();
    initApp();
}

