/* ==================== 初始化 ==================== */
let currentPeriod = 1;
let timerState = 'betting';
let countdown = 120;
let timerInterval = null;
let aiEnabled = false;
let aiInterval = null;

const COST = 10;
const TNAMES = {ssq:'双色球', dlt:'大乐透', plw:'排列五'};
let DRAW_INTERVAL = 120;

let picks = {
    ssq: {reds:new Set(), blue:null},
    dlt: {front:new Set(), back:new Set()},
    plw: [null,null,null,null,null]
};
let pendingBets = {ssq:[], dlt:[], plw:[]};

function initApp() {
    currentPeriod = userData?.period || 1;
    DRAW_INTERVAL = userData?.interval || 120;
    
    buildGrids();
    setupTabs();
    updateCheckinBtn();
    renderStats();
    renderAchievements();
    renderBets();
    startTimer();
}

function setupTabs() {
    document.querySelectorAll('.tab-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            const tab = btn.dataset.tab;
            document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
            document.querySelectorAll('.panel').forEach(p => p.classList.remove('active'));
            btn.classList.add('active');
            document.getElementById('panel-' + tab).classList.add('active');
        });
    });
}

/* ==================== 定时器 & 开奖 ==================== */
function startTimer() {
    if (timerInterval) clearInterval(timerInterval);
    countdown = DRAW_INTERVAL;
    timerState = 'betting';
    
    timerInterval = setInterval(() => {
        countdown--;
        updateTimerUI();
        
        if (countdown <= 0) {
            if (timerState === 'betting') {
                performDraw();
            } else if (timerState === 'drawn') {
                nextPeriod();
            }
        }
    }, 1000);
}

function updateTimerUI() {
    const min = Math.floor(countdown / 60);
    const sec = countdown % 60;
    document.getElementById('timerCount').textContent = 
        `${String(min).padStart(2,'0')}:${String(sec).padStart(2,'0')}`;
    document.getElementById('timerPhase').textContent = 
        timerState === 'betting' ? '🟢 投注中' : '🔴 已开奖';
    document.getElementById('currentPeriodNum').textContent = currentPeriod;
}

async function performDraw() {
    timerState = 'drawn';
    countdown = 10;
    
    // 生成开奖号码
    const ssqResult = {reds: pickUnique(6,1,33), blue: srand(1,16)};
    const dltResult = {front: pickUnique(5,1,35), back: pickUnique(2,1,12)};
    const plwResult = Array.from({length:5}, () => srand(0,9));
    
    // 计算奖金
    let totalWin = 0;
    
    userData.bets.forEach(bet => {
        if (bet.period !== currentPeriod) return;
        
        let win = 0;
        if (bet.type === 'ssq') {
            win = calculateSSQWin(bet.numbers, ssqResult);
        } else if (bet.type === 'dlt') {
            win = calculateDLTWin(bet.numbers, dltResult);
        } else if (bet.type === 'plw') {
            win = calculatePLWWin(bet.numbers, plwResult);
        }
        
        win *= bet.multiplier || 1;
        totalWin += win;
        bet.win = win;
        bet.drawNumbers = bet.type === 'ssq' ? ssqResult : 
                         bet.type === 'dlt' ? dltResult : plwResult;
    });
    
    if (totalWin > 0) {
        addPoints(totalWin);
    }
    
    // 保存到历史
    const historyItem = {
        period: currentPeriod,
        type: 'all',
        ssq: ssqResult,
        dlt: dltResult,
        plw: plwResult,
        timestamp: new Date().toISOString(),
        wins: totalWin
    };
    
    if (!userData.history) userData.history = [];
    userData.history.unshift(historyItem);
    if (userData.history.length > 100) userData.history = userData.history.slice(0, 100);
    
    userData.stats.totalDraws = (userData.stats.totalDraws || 0) + 1;
    userData.stats.totalEarned = (userData.stats.totalEarned || 0) + totalWin;
    
    // 保存到期数
    userData.period = currentPeriod;
    
    saveToGitHub();
    
    showToast(`第${currentPeriod}期开奖！${totalWin > 0 ? '🎉 中奖 ' + totalWin + ' 积分' : '😢 未中奖'}`, 
              totalWin > 0 ? 'success' : 'warning');
    
    renderBets();
    renderHistory();
    renderStats();
}

function nextPeriod() {
    currentPeriod++;
    userData.period = currentPeriod;
    userData.bets = [];
    pendingBets = {ssq:[], dlt:[], plw:[]};
    
    saveToGitHub();
    
    startTimer();
    renderBets();
    showToast(`第${currentPeriod}期开始投注！`, 'success');
}

/* ==================== 随机数生成 ==================== */
function srand(min, max) {
    const a = new Uint32Array(1);
    crypto.getRandomValues(a);
    return min + (a[0] % (max - min + 1));
}

function pickUnique(cnt, min, max) {
    const s = new Set();
    while (s.size < cnt) s.add(srand(min, max));
    return [...s].sort((a, b) => a - b);
}

/* ==================== 中奖计算 ==================== */
function calculateSSQWin(bet, result) {
    const redMatch = bet.reds.filter(n => result.reds.includes(n)).length;
    const blueMatch = bet.blue === result.blue;
    
    if (redMatch === 6 && blueMatch) return 50000;
    if (redMatch === 6) return 10000;
    if (redMatch === 5 && blueMatch) return 3000;
    if (redMatch === 5) return 200;
    if (redMatch === 4 && blueMatch) return 200;
    if (redMatch === 4) return 10;
    if (redMatch === 3 && blueMatch) return 10;
    if (redMatch === 2 && blueMatch) return 5;
    if (redMatch === 1 && blueMatch) return 5;
    if (blueMatch) return 5;
    return 0;
}

function calculateDLTWin(bet, result) {
    const frontMatch = bet.front.filter(n => result.front.includes(n)).length;
    const backMatch = bet.back.filter(n => result.back.includes(n)).length;
    
    if (frontMatch === 5 && backMatch === 2) return 50000;
    if (frontMatch === 5 && backMatch === 1) return 10000;
    if (frontMatch === 5) return 3000;
    if (frontMatch === 4 && backMatch === 2) return 3000;
    if (frontMatch === 4 && backMatch === 1) return 300;
    if (frontMatch === 3 && backMatch === 2) return 200;
    if (frontMatch === 4) return 100;
    if (frontMatch === 3 && backMatch === 1) return 10;
    if (frontMatch === 2 && backMatch === 2) return 10;
    if (frontMatch === 3) return 5;
    if (frontMatch === 1 && backMatch === 2) return 5;
    if (backMatch === 2) return 5;
    return 0;
}

function calculatePLWWin(bet, result) {
    let match = 0;
    for (let i = 0; i < 5; i++) {
        if (bet[i] === result[i]) match++;
        else break;
    }
    
    if (match === 5) return 10000;
    if (match === 4) return 1000;
    if (match === 3) return 100;
    if (match === 2) return 10;
    if (match === 1) return 2;
    return 0;
}

/* ==================== 选号面板 ==================== */
function buildGrids() {
    const mkCell = (parent, num, onClick, pad=true) => {
        const c = document.createElement('div');
        c.className = 'num-cell';
        c.textContent = pad ? String(num).padStart(2,'0') : num;
        c.dataset.num = num;
        c.onclick = () => onClick(num, c);
        parent.appendChild(c);
    };
    
    const ssqR = document.getElementById('ssq-red-grid'); ssqR.innerHTML = '';
    for (let i = 1; i <= 33; i++) mkCell(ssqR, i, (n,el) => toggleSSQRed(n,el));
    
    const ssqB = document.getElementById('ssq-blue-grid'); ssqB.innerHTML = '';
    for (let i = 1; i <= 16; i++) mkCell(ssqB, i, (n,el) => toggleSSQBlue(n,el));
    
    const dltF = document.getElementById('dlt-front-grid'); dltF.innerHTML = '';
    for (let i = 1; i <= 35; i++) mkCell(dltF, i, (n,el) => toggleDLTFront(n,el));
    
    const dltB = document.getElementById('dlt-back-grid'); dltB.innerHTML = '';
    for (let i = 1; i <= 12; i++) mkCell(dltB, i, (n,el) => toggleDLTBack(n,el));
    
    for (let d = 0; d < 5; d++) {
        const row = document.getElementById('plw-d' + d); row.innerHTML = '';
        for (let i = 0; i <= 9; i++) mkCell(row, i, (n,el) => togglePLW(d,n,el), false);
    }
}

function toggleSSQRed(n, el) {
    if (picks.ssq.reds.has(n)) {
        picks.ssq.reds.delete(n);
        el.classList.remove('selected');
    } else if (picks.ssq.reds.size < 6) {
        picks.ssq.reds.add(n);
        el.classList.add('selected');
    } else {
        showToast('红球最多6个', 'warning');
        return;
    }
    updateSSQPreview();
}

function toggleSSQBlue(n, el) {
    document.querySelectorAll('#ssq-blue-grid .num-cell').forEach(c => c.classList.remove('selected'));
    if (picks.ssq.blue === n) picks.ssq.blue = null;
    else {
        picks.ssq.blue = n;
        el.classList.add('selected');
    }
    updateSSQPreview();
}

function updateSSQPreview() {
    document.getElementById('ssq-red-count').textContent = picks.ssq.reds.size + '/6';
    document.getElementById('ssq-blue-count').textContent = (picks.ssq.blue ? 1 : 0) + '/1';
    const el = document.getElementById('ssq-preview');
    if (!picks.ssq.reds.size && !picks.ssq.blue) {
        el.innerHTML = '<span class="preview-empty">点击号码选号</span>';
        return;
    }
    let h = '';
    [...picks.ssq.reds].sort((a,b) => a-b).forEach(n => {
        h += `<span class="pball red">${String(n).padStart(2,'0')}</span>`;
    });
    if (picks.ssq.blue) h += `<span class="pball blue">${String(picks.ssq.blue).padStart(2,'0')}</span>`;
    el.innerHTML = h;
}

function toggleDLTFront(n, el) {
    if (picks.dlt.front.has(n)) {
        picks.dlt.front.delete(n);
        el.classList.remove('selected');
    } else if (picks.dlt.front.size < 5) {
        picks.dlt.front.add(n);
        el.classList.add('selected');
    } else {
        showToast('前区最多5个', 'warning');
        return;
    }
    updateDLTPreview();
}

function toggleDLTBack(n, el) {
    if (picks.dlt.back.has(n)) {
        picks.dlt.back.delete(n);
        el.classList.remove('selected');
    } else if (picks.dlt.back.size < 2) {
        picks.dlt.back.add(n);
        el.classList.add('selected');
    } else {
        showToast('后区最多2个', 'warning');
        return;
    }
    updateDLTPreview();
}

function updateDLTPreview() {
    document.getElementById('dlt-front-count').textContent = picks.dlt.front.size + '/5';
    document.getElementById('dlt-back-count').textContent = picks.dlt.back.size + '/2';
    const el = document.getElementById('dlt-preview');
    if (!picks.dlt.front.size && !picks.dlt.back.size) {
        el.innerHTML = '<span class="preview-empty">点击号码选号</span>';
        return;
    }
    let h = '';
    [...picks.dlt.front].sort((a,b) => a-b).forEach(n => {
        h += `<span class="pball red">${String(n).padStart(2,'0')}</span>`;
    });
    if (picks.dlt.back.size) {
        h += '<span class="pdiv">+</span>';
        [...picks.dlt.back].sort((a,b) => a-b).forEach(n => {
            h += `<span class="pball blue">${String(n).padStart(2,'0')}</span>`;
        });
    }
    el.innerHTML = h;
}

function togglePLW(d, n, el) {
    document.querySelectorAll('#plw-d' + d + ' .num-cell').forEach(c => c.classList.remove('selected'));
    if (picks.plw[d] === n) picks.plw[d] = null;
    else {
        picks.plw[d] = n;
        el.classList.add('selected');
    }
    updatePLWPreview();
}

function updatePLWPreview() {
    const el = document.getElementById('plw-preview');
    if (picks.plw.every(n => n === null)) {
        el.innerHTML = '<span class="preview-empty">每位选1个数字</span>';
        return;
    }
    el.innerHTML = picks.plw.map(n => `<span class="pball green">${n !== null ? n : '?'}</span>`).join('');
}

/* ==================== 机选 & 清空 ==================== */
function randomPick(type) {
    if (type === 'ssq') {
        document.querySelectorAll('#ssq-red-grid .num-cell, #ssq-blue-grid .num-cell').forEach(c => c.classList.remove('selected'));
        picks.ssq = {reds: new Set(pickUnique(6,1,33)), blue: srand(1,16)};
        document.querySelectorAll('#ssq-red-grid .num-cell').forEach(c => {
            if (picks.ssq.reds.has(+c.dataset.num)) c.classList.add('selected');
        });
        document.querySelectorAll('#ssq-blue-grid .num-cell').forEach(c => {
            if (+c.dataset.num === picks.ssq.blue) c.classList.add('selected');
        });
        updateSSQPreview();
    } else if (type === 'dlt') {
        document.querySelectorAll('#dlt-front-grid .num-cell, #dlt-back-grid .num-cell').forEach(c => c.classList.remove('selected'));
        picks.dlt = {front: new Set(pickUnique(5,1,35)), back: new Set(pickUnique(2,1,12))};
        document.querySelectorAll('#dlt-front-grid .num-cell').forEach(c => {
            if (picks.dlt.front.has(+c.dataset.num)) c.classList.add('selected');
        });
        document.querySelectorAll('#dlt-back-grid .num-cell').forEach(c => {
            if (picks.dlt.back.has(+c.dataset.num)) c.classList.add('selected');
        });
        updateDLTPreview();
    } else {
        for (let d = 0; d < 5; d++) {
            document.querySelectorAll('#plw-d' + d + ' .num-cell').forEach(c => c.classList.remove('selected'));
        }
        picks.plw = Array.from({length:5}, () => srand(0,9));
        for (let d = 0; d < 5; d++) {
            document.querySelectorAll('#plw-d' + d + ' .num-cell').forEach(c => {
                if (+c.dataset.num === picks.plw[d]) c.classList.add('selected');
            });
        }
        updatePLWPreview();
    }
}

function clearPick(type) {
    if (type === 'ssq') {
        document.querySelectorAll('#ssq-red-grid .num-cell, #ssq-blue-grid .num-cell').forEach(c => c.classList.remove('selected'));
        picks.ssq = {reds: new Set(), blue: null};
        updateSSQPreview();
    } else if (type === 'dlt') {
        document.querySelectorAll('#dlt-front-grid .num-cell, #dlt-back-grid .num-cell').forEach(c => c.classList.remove('selected'));
        picks.dlt = {front: new Set(), back: new Set()};
        updateDLTPreview();
    } else {
        for (let d = 0; d < 5; d++) {
            document.querySelectorAll('#plw-d' + d + ' .num-cell').forEach(c => c.classList.remove('selected'));
        }
        picks.plw = [null, null, null, null, null];
        updatePLWPreview();
    }
}

/* ==================== 添加投注 ==================== */
function addBet(type) {
    const mult = parseInt(document.getElementById(type + '-multiplier').value);
    
    if (type === 'ssq') {
        if (picks.ssq.reds.size !== 6 || !picks.ssq.blue) {
            showToast('请选满6红1蓝', 'warning');
            return;
        }
        pendingBets.ssq.push({
            numbers: {reds: [...picks.ssq.reds], blue: picks.ssq.blue},
            multiplier: mult,
            cost: COST * mult
        });
    } else if (type === 'dlt') {
        if (picks.dlt.front.size !== 5 || picks.dlt.back.size !== 2) {
            showToast('请选满5前2后', 'warning');
            return;
        }
        pendingBets.dlt.push({
            numbers: {front: [...picks.dlt.front], back: [...picks.dlt.back]},
            multiplier: mult,
            cost: COST * mult
        });
    } else {
        if (picks.plw.some(n => n === null)) {
            showToast('请选满5位数字', 'warning');
            return;
        }
        pendingBets.plw.push({
            numbers: [...picks.plw],
            multiplier: mult,
            cost: COST * mult
        });
    }
    
    renderPendingBets(type);
    clearPick(type);
    showToast('已添加1注', 'success');
}

function renderPendingBets(type) {
    const el = document.getElementById(type + '-added-bets');
    const bets = pendingBets[type];
    if (!bets.length) {
        el.innerHTML = '';
        return;
    }
    
    let html = '<div class="pending-list">';
    bets.forEach((bet, i) => {
        html += `<div class="pending-item">
            <span class="pending-nums">${formatNumbers(type, bet.numbers)}</span>
            <span class="pending-mult">${bet.multiplier}倍</span>
            <span class="pending-cost">${bet.cost}积分</span>
            <button class="pending-del" onclick="removePendingBet('${type}',${i})">✕</button>
        </div>`;
    });
    html += '</div>';
    el.innerHTML = html;
}

function removePendingBet(type, index) {
    pendingBets[type].splice(index, 1);
    renderPendingBets(type);
}

function formatNumbers(type, nums) {
    if (type === 'ssq') {
        return nums.reds.map(n => String(n).padStart(2,'0')).join(' ') + ' + ' + String(nums.blue).padStart(2,'0');
    } else if (type === 'dlt') {
        return nums.front.map(n => String(n).padStart(2,'0')).join(' ') + ' + ' + nums.back.map(n => String(n).padStart(2,'0')).join(' ');
    } else {
        return nums.join('');
    }
}

/* ==================== 提交投注 ==================== */
function submitBets(type) {
    if (timerState !== 'betting') {
        showToast('当前不在投注时间', 'warning');
        return;
    }
    
    const bets = pendingBets[type];
    if (!bets.length) {
        showToast('请先添加至少一注', 'warning');
        return;
    }
    
    const totalCost = bets.reduce((s, b) => s + b.cost, 0);
    if (getPoints() < totalCost) {
        showToast('积分不足', 'error');
        return;
    }
    
    deductPoints(totalCost);
    
    bets.forEach(bet => {
        userData.bets.push({
            type: type,
            numbers: bet.numbers,
            multiplier: bet.multiplier,
            period: currentPeriod,
            cost: bet.cost,
            time: new Date().toISOString()
        });
    });
    
    userData.stats.totalSpent = (userData.stats.totalSpent || 0) + totalCost;
    
    saveToGitHub();
    
    pendingBets[type] = [];
    renderPendingBets(type);
    renderBets();
    
    showToast('投注成功！消耗 ' + totalCost + ' 积分', 'success');
}

/* ==================== 渲染投注列表 ==================== */
function renderBets() {
    const el = document.getElementById('betsList');
    if (!el) return;
    
    const bets = userData?.bets || [];
    if (!bets.length) {
        el.innerHTML = '<p class="empty-msg">暂无投注</p>';
        document.getElementById('betsSummary').innerHTML = '';
        return;
    }
    
    let html = '<div class="bets-list">';
    bets.slice().reverse().forEach(bet => {
        const hasWin = bet.win !== undefined;
        html += `<div class="bet-item ${hasWin ? 'bet-result' : ''}">
            <div class="bet-header">
                <span class="bet-type">${TNAMES[bet.type]}</span>
                <span class="bet-period">第${bet.period}期</span>
                <span class="bet-mult">${bet.multiplier}倍</span>
            </div>
            <div class="bet-nums">${formatNumbers(bet.type, bet.numbers)}</div>
            ${hasWin ? `<div class="bet-result-info">
                <span class="bet-draw">开奖：${formatDrawResult(bet.type, bet.drawNumbers)}</span>
                <span class="bet-win ${bet.win > 0 ? 'win' : 'lose'}">${bet.win > 0 ? '🎉 +' + bet.win : '😢 未中奖'}</span>
            </div>` : ''}
        </div>`;
    });
    html += '</div>';
    el.innerHTML = html;
    
    const totalCost = bets.reduce((s, b) => s + b.cost, 0);
    const totalWin = bets.reduce((s, b) => s + (b.win || 0), 0);
    document.getElementById('betsSummary').innerHTML = `
        <div class="bets-summary">
            <span>总消耗：${totalCost} 积分</span>
            <span>总奖励：${totalWin} 积分</span>
            <span>净收益：${totalWin - totalCost} 积分</span>
        </div>
    `;
}

function formatDrawResult(type, result) {
    if (type === 'ssq') {
        return result.reds.map(n => String(n).padStart(2,'0')).join(' ') + ' + ' + String(result.blue).padStart(2,'0');
    } else if (type === 'dlt') {
        return result.front.map(n => String(n).padStart(2,'0')).join(' ') + ' + ' + result.back.map(n => String(n).padStart(2,'0')).join(' ');
    } else {
        return result.join('');
    }
}

/* ==================== 开奖记录 ==================== */
function switchHistoryTab(tab) {
    document.querySelectorAll('.hist-tab').forEach(t => t.classList.remove('active'));
    document.querySelector(`.hist-tab[data-htab="${tab}"]`).classList.add('active');
    renderHistory(tab);
}

function renderHistory(type) {
    const el = document.getElementById('historyContent');
    if (!el) return;
    
    const history = userData?.history || [];
    if (!history.length) {
        el.innerHTML = '<p class="empty-msg">暂无记录</p>';
        return;
    }
    
    let html = '<div class="history-list">';
    history.forEach(item => {
        html += `<div class="history-item">
            <div class="history-header">
                <span class="history-period">第${item.period}期</span>
                <span class="history-time">${new Date(item.timestamp).toLocaleString('zh-CN')}</span>
            </div>
            <div class="history-numbers">
                <div class="history-type">🔴 双色球：<span class="history-nums">${formatDrawResult('ssq', item.ssq)}</span></div>
                <div class="history-type">🔵 大乐透：<span class="history-nums">${formatDrawResult('dlt', item.dlt)}</span></div>
                <div class="history-type">🟢 排列五：<span class="history-nums">${formatDrawResult('plw', item.plw)}</span></div>
            </div>
            ${item.wins > 0 ? `<div class="history-win">🎉 中奖：${item.wins} 积分</div>` : ''}
        </div>`;
    });
    html += '</div>';
    el.innerHTML = html;
}

/* ==================== 统计 ==================== */
function renderStats() {
    const stats = userData?.stats || {};
    const checkin = userData?.checkin || {};
    
    document.getElementById('s-total').textContent = stats.totalDraws || 0;
    document.getElementById('s-spent').textContent = stats.totalSpent || 0;
    document.getElementById('s-earned').textContent = stats.totalEarned || 0;
    document.getElementById('s-checkin').textContent = checkin.consecutiveDays || 0;
}

/* ==================== 成就 ==================== */
function renderAchievements() {
    const el = document.getElementById('achList');
    if (!el) return;
    
    const achs = userData?.achievements || {};
    const list = [
        {id: 'first_bet', name: '初出茅庐', desc: '首次投注', icon: '🎯'},
        {id: 'first_win', name: '旗开得胜', desc: '首次中奖', icon: '🎉'},
        {id: 'checkin_7', name: '坚持不懈', desc: '连续签到7天', icon: '📅'},
        {id: 'checkin_30', name: '持之以恒', desc: '连续签到30天', icon: '🏆'},
        {id: 'spend_1000', name: '豪掷千金', desc: '累计消耗1000积分', icon: '💰'},
        {id: 'spend_10000', name: '一掷千金', desc: '累计消耗10000积分', icon: '💎'},
        {id: 'win_1000', name: '小有收获', desc: '累计奖励1000积分', icon: '🌟'},
        {id: 'win_10000', name: '大丰收', desc: '累计奖励10000积分', icon: '✨'}
    ];
    
    let html = '<div class="ach-list">';
    list.forEach(a => {
        const unlocked = achs[a.id];
        html += `<div class="ach-item ${unlocked ? 'unlocked' : 'locked'}">
            <span class="ach-icon">${a.icon}</span>
            <div class="ach-info">
                <div class="ach-name">${a.name}</div>
                <div class="ach-desc">${a.desc}</div>
            </div>
            <span class="ach-status">${unlocked ? '✅' : '🔒'}</span>
        </div>`;
    });
    html += '</div>';
    el.innerHTML = html;
}

/* ==================== 签到 ==================== */
function handleCheckin() {
    const c = userData.checkin;
    const today = new Date().toDateString();
    
    if (c.lastDate === today) {
        showToast('今日已签到', 'warning');
        return;
    }
    
    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    
    let streak = (c.lastDate === yesterday.toDateString()) ? (c.consecutiveDays || 0) + 1 : 1;
    let reward = 30;
    
    if (streak % 7 === 0) reward += 100;
    
    addPoints(reward);
    
    userData.checkin = {
        lastDate: today,
        consecutiveDays: streak
    };
    
    // 检查成就
    if (streak >= 7 && !userData.achievements.checkin_7) {
        userData.achievements.checkin_7 = true;
        showToast('🏆 解锁成就：坚持不懈', 'success');
    }
    if (streak >= 30 && !userData.achievements.checkin_30) {
        userData.achievements.checkin_30 = true;
        showToast('🏆 解锁成就：持之以恒', 'success');
    }
    
    saveToGitHub();
    
    showToast(`签到成功！+${reward}积分，连续${streak}天`, 'success');
    updateCheckinBtn();
    renderStats();
    renderAchievements();
}

function updateCheckinBtn() {
    const btn = document.getElementById('checkinBtn');
    if (!btn) return;
    
    const c = userData?.checkin || {};
    const today = new Date().toDateString();
    
    if (c.lastDate === today) {
        btn.disabled = true;
        btn.title = '今日已签到';
        btn.style.opacity = '0.5';
    } else {
        btn.disabled = false;
        btn.title = '签到';
        btn.style.opacity = '1';
    }
}

/* ==================== AI 投注 ==================== */
function toggleAIMenu() {
    const panel = document.getElementById('aiPanel');
    panel.style.display = panel.style.display === 'none' ? 'block' : 'none';
}

function toggleAI() {
    const toggle = document.getElementById('aiToggle');
    aiEnabled = toggle.checked;
    
    if (aiEnabled) {
        startAI();
        document.getElementById('aiStatus').textContent = '▶️ AI运行中...';
    } else {
        stopAI();
        document.getElementById('aiStatus').textContent = '⏸️ AI已关闭';
    }
}

function startAI() {
    if (aiInterval) clearInterval(aiInterval);
    aiInterval = setInterval(() => {
        if (timerState !== 'betting') return;
        
        const types = [];
        if (document.getElementById('ai-ssq').checked) types.push('ssq');
        if (document.getElementById('ai-dlt').checked) types.push('dlt');
        if (document.getElementById('ai-plw').checked) types.push('plw');
        
        const mult = parseInt(document.getElementById('ai-mult').value);
        const count = parseInt(document.getElementById('ai-count').value);
        
        types.forEach(type => {
            for (let i = 0; i < count; i++) {
                if (getPoints() < COST * mult) return;
                
                let nums;
                if (type === 'ssq') {
                    nums = {reds: pickUnique(6,1,33), blue: srand(1,16)};
                } else if (type === 'dlt') {
                    nums = {front: pickUnique(5,1,35), back: pickUnique(2,1,12)};
                } else {
                    nums = Array.from({length:5}, () => srand(0,9));
                }
                
                deductPoints(COST * mult);
                
                userData.bets.push({
                    type: type,
                    numbers: nums,
                    multiplier: mult,
                    period: currentPeriod,
                    cost: COST * mult,
                    time: new Date().toISOString()
                });
            }
        });
        
        userData.stats.totalSpent = (userData.stats.totalSpent || 0) + (COST * mult * count * types.length);
        saveToGitHub();
        renderBets();
        
    }, 5000); // 每5秒投注一次
}

function stopAI() {
    if (aiInterval) {
        clearInterval(aiInterval);
        aiInterval = null;
    }
}

/* ==================== 其他功能 ==================== */
function showUserMenu() {
    document.getElementById('userMenuModal').style.display = 'flex';
}

function exportData() {
    const data = JSON.stringify(userData, null, 2);
    const blob = new Blob([data], {type: 'application/json'});
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `lottery_data_${currentUser}_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
    document.getElementById('userMenuModal').style.display = 'none';
    showToast('导出成功', 'success');
}

function importData() {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json';
    input.onchange = async (e) => {
        const file = e.target.files[0];
        if (!file) return;
        
        const text = await file.text();
        try {
            const imported = JSON.parse(text);
            if (!imported.points && !imported.bets) {
                showToast('无效的数据文件', 'error');
                return;
            }
            
            if (!confirm('导入将覆盖当前数据，确定吗？')) return;
            
            Object.assign(userData, imported);
            saveToGitHub();
            
            showToast('导入成功，刷新页面生效', 'success');
            setTimeout(() => location.reload(), 1500);
            
        } catch (e) {
            showToast('文件格式错误', 'error');
        }
    };
    input.click();
    document.getElementById('userMenuModal').style.display = 'none';
}

async function refreshFromCloud() {
    showToast('同步中...', 'info');
    try {
        const { content: allData } = await githubGet('data.json');
        userData = allData[currentUser];
        updatePointsUI();
        renderBets();
        renderHistory();
        renderStats();
        renderAchievements();
        showToast('同步成功', 'success');
    } catch (e) {
        showToast('同步失败', 'error');
    }
    document.getElementById('userMenuModal').style.display = 'none';
}

/* ==================== Toast 提示 ==================== */
function showToast(msg, type = 'info') {
    const existing = document.querySelector('.toast');
    if (existing) existing.remove();
    
    const toast = document.createElement('div');
    toast.className = `toast ${type}`;
    toast.textContent = msg;
    document.body.appendChild(toast);
    
    setTimeout(() => toast.classList.add('show'), 10);
    setTimeout(() => {
        toast.classList.remove('show');
        setTimeout(() => toast.remove(), 300);
    }, 3000);
}

/* ==================== 页面加载 ==================== */
window.addEventListener('DOMContentLoaded', async () => {
    // 检查连接状态
    try {
        await githubGet('users.json');
        document.getElementById('serverStatus').textContent = '✅ 服务器连接正常';
        document.getElementById('serverStatus').style.color = '#2ecc71';
    } catch (e) {
        document.getElementById('serverStatus').textContent = '❌ 服务器连接失败，请检查配置';
        document.getElementById('serverStatus').style.color = '#e74c3c';
    }
});